function login(){app.innerHTML=`<div class="login-page"><div class="login-card"><div class="brand"><div class="brand-badge">📍</div><div>سامانه بازرسی پاکدشت</div></div><h1 style="margin-top:20px">ورود به سامانه</h1><p class="muted">حساب واقعی شما از طریق Backend احراز هویت می‌شود.</p><div class="field"><label>نام کاربری</label><input id="username" autocomplete="username"></div><div class="field" style="margin-top:10px"><label>رمز عبور</label><input id="password" type="password" autocomplete="current-password"></div><div id="loginErr" class="alert hidden" style="margin-top:10px"></div><button id="loginBtn" class="btn primary" style="width:100%;margin-top:14px">ورود</button><button id="createBtn" class="btn ghost" style="width:100%;margin-top:8px">ایجاد حساب</button></div></div>`;$('#loginBtn').onclick=async()=>{try{const d=await api('auth/login',{method:'POST',body:JSON.stringify({username:$('#username').value,password:$('#password').value})});state.token=null;state.user=d.user;save();renderShell()}catch(e){$('#loginErr').textContent=e.message;$('#loginErr').classList.remove('hidden')}};$('#createBtn').onclick=register}
function register(){app.innerHTML=`<div class="login-page"><div class="login-card"><h1>ایجاد حساب</h1><p class="muted">برای Manager نیاز به کد دعوت معتبر سازمان دارید.</p><div class="form-grid"><div class="field"><label>نام</label><input id="f1"></div><div class="field"><label>نام خانوادگی</label><input id="f2"></div><div class="field"><label>کد پرسنلی</label><input id="f3"></div><div class="field"><label>موبایل</label><input id="f4" inputmode="tel"></div><div class="field"><label>نام کاربری</label><input id="f5"></div><div class="field"><label>رمز عبور</label><input id="f6" type="password"></div><div class="field"><label>نام سازمان/اتحادیه</label><input id="f7" value="اتحادیه نمونه پاکدشت"></div><div class="field"><label>نقش</label><select id="f8"><option value="INSPECTOR">بازرس</option><option value="MANAGER">مدیر</option></select></div></div><div class="field" style="margin-top:10px"><label>کد دعوت مدیر (فقط برای Manager)</label><input id="f9" placeholder="در حالت Demo: PAKDASHT-DEMO-MGR"></div><div id="regErr" class="alert hidden" style="margin-top:10px"></div><div class="row" style="margin-top:14px"><button class="btn primary" id="reg">ساخت حساب</button><button class="btn ghost" id="back">بازگشت</button></div></div></div>`;$('#back').onclick=login;$('#reg').onclick=async()=>{try{await api('auth/register',{method:'POST',body:JSON.stringify({firstName:$('#f1').value,lastName:$('#f2').value,personnelCode:$('#f3').value,mobile:$('#f4').value,username:$('#f5').value,password:$('#f6').value,organizationName:$('#f7').value,role:$('#f8').value,inviteCode:$('#f9').value})});toast('حساب ساخته شد؛ اکنون وارد شوید');setTimeout(login,700)}catch(e){$('#regErr').textContent=e.message;$('#regErr').classList.remove('hidden')}}}
async function load(){const s=await api('shops');state.shops=s.items;const m=await api('missions');state.missions=m.items;if(state.user.role==='INSPECTOR'){const active=state.missions.find(x=>x.status==='ACTIVE'&&x.inspector_id===state.user.id);state.activeMission=active?.id||null;if(active){try{const route=await api('route/'+active.id);state.track=route.points||[]}catch{state.track=[]}}else state.track=[]}if(state.user.role==='MANAGER'){state.employees=(await api('employees')).items;state.monitoring=(await api('monitoring')).items}}
function navItems(){return state.user.role==='INSPECTOR'?[['dashboard','🏠','داشبورد'],['map','🗺️','نقشه'],['missions','🚀','مأموریت‌ها'],['shops','🏪','واحدها'],['inspections','📋','بازرسی‌ها'],['warnings','⚠️','اخطارها'],['profile','👤','پروفایل']]:[['dashboard','📊','داشبورد'],['monitoring','📡','نظارت زنده'],['employees','👥','کارمندان'],['map','🗺️','نقشه'],['shops','🏪','واحدها'],['missions','🚀','مأموریت‌ها'],['routes','🧭','مسیرها'],['reports','📈','گزارش‌ها'],['profile','👤','پروفایل']];}
function renderShell(){app.innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand"><div class="brand-badge">📍</div><div>سامانه مدیریت بازرسی</div></div><div class="row"><span>${esc(state.user.firstName)} ${esc(state.user.lastName)}</span><span class="pill">${state.user.role==='MANAGER'?'مدیر':'بازرس'}</span><span id="net" class="online">Online</span><button id="logout" class="btn secondary">خروج</button></div></header><div class="layout"><aside class="sidebar"><nav class="nav">${navItems().map(n=>`<button data-page="${n[0]}" class="${state.page===n[0]?'active':''}"><span>${n[1]}</span>${n[2]}</button>`).join('')}</nav></aside><main class="main" id="content"></main></div></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;renderPage()});$('#logout').onclick=async()=>{try{await api('auth/logout',{method:'POST'})}catch{} state.token=null;state.user=null;save();login()};updateNet();renderPage()}
function updateNet(){const n=$('#net');if(!n)return;n.className=state.online?'online':'offline';n.textContent=state.online?'Online':'Offline'}
function renderPage(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));const c=$('#content'); if(!c)return; const p=state.page; if(p==='dashboard')dashboard(c); else if(p==='map')mapPage(c); else if(p==='missions')missions(c); else if(p==='shops')shops(c); else if(p==='inspections')genericList(c,'بازرسی‌ها','inspections'); else if(p==='warnings')genericList(c,'اخطارها','warnings'); else if(p==='monitoring')monitoring(c); else if(p==='employees')employees(c); else if(p==='routes')routes(c); else if(p==='reports')reports(c); else profile(c)}
function dashboard(c){const active=state.missions.filter(x=>x.status==='ACTIVE').length; c.innerHTML=`<div class="page-head"><div><h1>${state.user.role==='MANAGER'?'داشبورد مدیر':'داشبورد بازرس'}</h1><div class="muted">نمای کلی فعالیت سامانه</div></div>${state.user.role==='INSPECTOR'?`<button class="btn primary" id="start">🚀 شروع مأموریت</button>`:''}</div><div class="grid stats"><div class="card stat"><div class="label">کارمندان</div><div class="value">${state.user.role==='MANAGER'?state.employees.length:1}</div></div><div class="card stat"><div class="label">مأموریت فعال</div><div class="value">${active}</div></div><div class="card stat"><div class="label">واحدهای صنفی</div><div class="value">${state.shops.length}</div></div><div class="card stat"><div class="label">بازرسی‌های امروز</div><div class="value">${state.missions.length}</div></div><div class="card stat"><div class="label">وضعیت اینترنت</div><div class="value" style="font-size:18px">${state.online?'متصل':'آفلاین'}</div></div></div><div class="grid two" style="margin-top:14px"><div class="card"><h3>مأموریت‌های اخیر</h3>${state.missions.slice(0,6).map(m=>`<div class="row" style="justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line)"><span>${esc(m.id.slice(0,8))}…</span><span class="pill ${m.status==='ACTIVE'?'ok':''}">${esc(m.status)}</span></div>`).join('')||'<div class="empty">موردی نیست</div>'}</div><div class="card"><h3>وضعیت GPS</h3><p class="muted">GPS فقط هنگام مأموریت فعال استفاده می‌شود.</p><div id="gpsStatus" class="pill">آماده</div></div></div>`;if($('#start'))$('#start').onclick=startMission}
function mapPage(c){c.innerHTML=`<div class="page-head"><div><h1>نقشه پاکدشت</h1><div class="muted">واحدها، موقعیت شما و مسیر مأموریت</div></div><div class="row"><button class="btn primary" id="addShop">+ ثبت واحد</button>${state.user.role==='INSPECTOR'?(state.activeMission?'<button class="btn danger" id="endMission">پایان مأموریت</button>':'<button class="btn primary" id="start2">شروع مأموریت</button>'):''}</div></div><div class="card" style="padding:8px"><div class="map" id="map"><div class="map-canvas" id="mapCanvas"></div><div class="map-controls"><button id="zin">＋</button><button id="zout">−</button><button id="loc">⌾</button></div><div class="bottom-action"><span class="pill">${state.shops.length} واحد</span></div></div></div>`;initMap();$('#addShop').onclick=()=>shopModal();if($('#start2'))$('#start2').onclick=startMission;if($('#endMission'))$('#endMission').onclick=endMission;$('#zin').onclick=()=>{state.mapZoom=Math.min(18,state.mapZoom+1);drawMap()};$('#zout').onclick=()=>{state.mapZoom=Math.max(10,state.mapZoom-1);drawMap()};$('#loc').onclick=()=>requestLocation(true)}
function geoXY(lat,lng,z){const n=2**z;return {x:(lng+180)/360*n,y:(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n}}
function xyGeo(x,y,z){const n=2**z,lng=x/n*360-180,lat=180/Math.PI*Math.atan(Math.sinh(Math.PI*(1-2*y/n)));return {lat,lng}}
function initMap(){const el=$('#map'),canvas=$('#mapCanvas');if(!el)return;state.map={el,canvas,px:{x:0,y:0},drag:null};const center=geoXY(state.mapCenter.lat,state.mapCenter.lng,state.mapZoom);state.map.px=center;drawMap();el.onwheel=e=>{e.preventDefault();state.mapZoom=Math.max(10,Math.min(18,state.mapZoom+(e.deltaY<0?1:-1)));drawMap()};el.onpointerdown=e=>{state.map.drag={x:e.clientX,y:e.clientY,cx:state.mapCenter.lat,cl:state.mapCenter.lng};el.setPointerCapture(e.pointerId)};el.onpointerup=e=>{state.map.drag=null};el.onpointermove=e=>{if(!state.map.drag)return;const dx=e.clientX-state.map.drag.x,dy=e.clientY-state.map.drag.y;const z=state.mapZoom;const c=geoXY(state.map.drag.cx,state.map.drag.cl,z);const p=xyGeo(c.x-dx/256,c.y-dy/256,z);state.mapCenter=p;drawMap()};el.onclick=e=>{if(e.target.closest('.marker'))return; if(state.addingShop){const r=el.getBoundingClientRect(),center=geoXY(state.mapCenter.lat,state.mapCenter.lng,state.mapZoom);const worldX=center.x+(e.clientX-r.left-r.width/2)/256,worldY=center.y+(e.clientY-r.top-r.height/2)/256;const g=xyGeo(worldX,worldY,state.mapZoom);shopModal(g)}}}
function drawMap(){const m=state.map;if(!m)return;const {el,canvas}=m;canvas.innerHTML='';const z=state.mapZoom,c=geoXY(state.mapCenter.lat,state.mapCenter.lng,z),w=el.clientWidth,h=el.clientHeight;const tx=Math.floor(c.x),ty=Math.floor(c.y);for(let ix=tx-2;ix<=tx+2;ix++)for(let iy=ty-2;iy<=ty+2;iy++){const im=document.createElement('img');im.className='tile';im.src=`https://tile.openstreetmap.org/${z}/${ix}/${iy}.png`;im.onerror=()=>im.remove();im.style.left=(ix-c.x)*256+w/2+'px';im.style.top=(iy-c.y)*256+h/2+'px';canvas.appendChild(im)};const add=(lat,lng,cls,title,emoji)=>{const p=geoXY(lat,lng,z),x=(p.x-c.x)*256+w/2,y=(p.y-c.y)*256+h/2; if(x<-40||x>w+40||y<-40||y>h+40)return;const d=document.createElement('button');d.className='marker '+cls;d.title=title;d.style.left=x+'px';d.style.top=y+'px';d.innerHTML=`<span>${emoji}</span>`;d.onclick=e=>{e.stopPropagation();if(cls.includes('shop'))shopModalById(title)};canvas.appendChild(d)};state.shops.forEach(s=>add(s.latitude,s.longitude,'shop',s.id,'🏪'));if(state.activeMission&&state.track.length){const pts=state.track.map(t=>{const p=geoXY(t.latitude,t.longitude,z);return [(p.x-c.x)*256+w/2,(p.y-c.y)*256+h/2]});const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.style.position='absolute';svg.style.inset=0;svg.innerHTML=`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#dc2626" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>`;canvas.appendChild(svg)};if(state.myLocation)add(state.myLocation.lat,state.myLocation.lng,'me','me','●')}
function drawHistoricalRouteMap(points,mission){const el=$('#routeMap'),canvas=$('#routeMapCanvas');if(!el||!canvas)return;canvas.innerHTML='';const valid=(points||[]).filter(p=>validCoordinate(p.latitude,p.longitude));if(!valid.length){canvas.innerHTML='<div class="empty" style="padding-top:180px">برای این مأموریت نقطه GPS ذخیره‌شده‌ای وجود ندارد؛ مسیر جعلی نمایش داده نمی‌شود.</div>';return}let z=18;const projected=level=>valid.map(p=>geoXY(Number(p.latitude),Number(p.longitude),level));while(z>10){const ps=projected(z),xs=ps.map(p=>p.x),ys=ps.map(p=>p.y);if((Math.max(...xs)-Math.min(...xs))*256<=el.clientWidth*.75&&(Math.max(...ys)-Math.min(...ys))*256<=el.clientHeight*.75)break;z--}const ps=projected(z),cx=(Math.min(...ps.map(p=>p.x))+Math.max(...ps.map(p=>p.x)))/2,cy=(Math.min(...ps.map(p=>p.y))+Math.max(...ps.map(p=>p.y)))/2,w=el.clientWidth,h=el.clientHeight;const tx=Math.floor(cx),ty=Math.floor(cy);for(let ix=tx-2;ix<=tx+2;ix++)for(let iy=ty-2;iy<=ty+2;iy++){const im=document.createElement('img');im.className='tile';im.src=`https://tile.openstreetmap.org/${z}/${ix}/${iy}.png`;im.onerror=()=>im.remove();im.style.left=(ix-cx)*256+w/2+'px';im.style.top=(iy-cy)*256+h/2+'px';canvas.appendChild(im)}const xy=valid.map(p=>{const q=geoXY(Number(p.latitude),Number(p.longitude),z);return[(q.x-cx)*256+w/2,(q.y-cy)*256+h/2]});if(xy.length>=2){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.style.position='absolute';svg.style.inset=0;svg.innerHTML=`<polyline points="${xy.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#dc2626" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>`;canvas.appendChild(svg)}const marker=(p,cls,label)=>{const q=geoXY(Number(p.latitude),Number(p.longitude),z),x=(q.x-cx)*256+w/2,y=(q.y-cy)*256+h/2,d=document.createElement('div');d.className='marker '+cls;d.title=label;d.style.left=x+'px';d.style.top=y+'px';d.innerHTML=`<span>${label}</span>`;canvas.appendChild(d)};marker(valid[0],'me','S');if(valid.length>1)marker(valid[valid.length-1],'shop','E')}
function requestLocation(center=false){if(!navigator.geolocation){toast('مرورگر GPS را پشتیبانی نمی‌کند');return}navigator.geolocation.getCurrentPosition(pos=>{state.myLocation={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy};if(center){state.mapCenter=state.myLocation;drawMap()}toast('موقعیت دریافت شد')},()=>toast('دسترسی Location رد شد؛ از تنظیمات مرورگر اجازه بدهید'),{enableHighAccuracy:true,timeout:10000,maximumAge:5000})}
async function startMission(){if(state.activeMission){toast('یک مأموریت فعال از قبل وجود دارد');return}if(!navigator.geolocation){toast('GPS در این مرورگر در دسترس نیست');return}toast('در حال دریافت موقعیت…');navigator.geolocation.getCurrentPosition(async p=>{try{const d=await api('missions',{method:'POST',body:JSON.stringify({latitude:p.coords.latitude,longitude:p.coords.longitude,startTime:new Date().toISOString()})});state.activeMission=d.id;state.track=[{latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,timestamp:new Date().toISOString()}];state.myLocation={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy};state.mapCenter=state.myLocation;beginWatch();await load();toast('مأموریت شروع شد');renderPage()}catch(e){toast(e.message)}},()=>toast('برای شروع مأموریت باید اجازه Location بدهید'),{enableHighAccuracy:true,timeout:12000,maximumAge:0})}
function beginWatch(){if(state.watchId!==null)navigator.geolocation.clearWatch(state.watchId);state.watchId=navigator.geolocation.watchPosition(async p=>{const point={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,timestamp:new Date().toISOString()};state.myLocation={lat:point.latitude,lng:point.longitude,accuracy:point.accuracy};state.track.push(point);if(state.activeMission){try{await api(`missions/${state.activeMission}/track`,{method:'POST',body:JSON.stringify(point)})}catch(e){await enqueue('track_point',crypto.randomUUID(),point,state.activeMission)}}if(state.map)drawMap() },()=>toast('GPS به‌روزرسانی نشد'),{enableHighAccuracy:true,maximumAge:10000,timeout:20000})}
async function endMission(){if(!state.activeMission)return;requestLocation();setTimeout(async()=>{const p=state.myLocation;if(!p){toast('موقعیت پایان دریافت نشد');return}try{await api(`missions/${state.activeMission}/end`,{method:'POST',body:JSON.stringify({latitude:p.lat,longitude:p.lng,endTime:new Date().toISOString()})});if(state.watchId!==null)navigator.geolocation.clearWatch(state.watchId);state.watchId=null;state.activeMission=null;state.track=[];await load();toast('مأموریت با موفقیت پایان یافت');renderPage()}catch(e){toast(e.message)}},1200)}
const IDB={db:null,open(){return new Promise((resolve,reject)=>{if(this.db)return resolve(this.db);const r=indexedDB.open('pakdasht-inspection',1);r.onupgradeneeded=()=>r.result.createObjectStore('sync',{keyPath:'id'});r.onsuccess=()=>{this.db=r.result;resolve(this.db)};r.onerror=()=>reject(r.error)})},async put(v){const db=await this.open();return new Promise((res,rej)=>{const q=db.transaction('sync','readwrite').objectStore('sync').put(v);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)} )},async all(){const db=await this.open();return new Promise((res,rej)=>{const q=db.transaction('sync').objectStore('sync').getAll();q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})},async del(id){const db=await this.open();return new Promise((res,rej)=>{const q=db.transaction('sync','readwrite').objectStore('sync').delete(id);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)})}};
async function enqueue(type,id,payload,missionId=null){const item={id,type,payload,missionId,status:'pending',createdAt:new Date().toISOString(),attempts:0};try{await IDB.put(item)}catch{const q=JSON.parse(localStorage.getItem('syncQueue')||'[]');if(!q.some(x=>x.id===item.id))q.push(item);localStorage.setItem('syncQueue',JSON.stringify(q))}toast('این داده آفلاین ذخیره شد و بعداً Sync می‌شود')}
function shopModal(g){state.addingShop=false;const lat=g?.lat??state.myLocation?.lat??35.474,lng=g?.lng??state.myLocation?.lng??51.685;modal(`<h2>ثبت واحد صنفی</h2><div class="form-grid"><div class="field"><label>نام واحد صنفی *</label><input id="s1"></div><div class="field"><label>نام صاحب/مسئول</label><input id="s2"></div><div class="field"><label>موبایل</label><input id="s3"></div><div class="field"><label>کد ملی</label><input id="s4" maxlength="10"></div><div class="field"><label>شماره پروانه</label><input id="s5"></div><div class="field"><label>نوع صنف</label><input id="s6"></div><div class="field"><label>آدرس</label><input id="s7"></div><div class="field"><label>Latitude</label><input id="s8" value="${lat.toFixed(6)}"></div><div class="field"><label>Longitude</label><input id="s9" value="${lng.toFixed(6)}"></div></div><div class="field" style="margin-top:10px"><label>توضیحات</label><textarea id="s10"></textarea></div><div class="row" style="margin-top:12px"><button class="btn primary" id="saveShop">ذخیره</button><button class="btn ghost" id="close">انصراف</button></div>`);$('#close').onclick=closeModal;$('#saveShop').onclick=async()=>{const national=$('#s4').value;if(national&&(!/^\d{10}$/.test(national)))return toast('کد ملی باید ۱۰ رقم باشد');try{await api('shops',{method:'POST',body:JSON.stringify({name:$('#s1').value,ownerName:$('#s2').value,mobile:$('#s3').value,nationalId:national,businessLicense:$('#s5').value,category:$('#s6').value,address:$('#s7').value,latitude:Number($('#s8').value),longitude:Number($('#s9').value),description:$('#s10').value})});closeModal();await load();toast('واحد ثبت شد');renderPage()}catch(e){toast(e.message)}}}
function shopModalById(id){const s=state.shops.find(x=>x.id===id);if(!s)return;modal(`<h2>${esc(s.name)}</h2><p class="muted">${esc(s.category||'بدون صنف')} · ${esc(s.address||'بدون آدرس')}</p><div class="three grid"><div class="card"><b>صاحب</b><div>${esc(s.owner_name)}</div></div><div class="card"><b>موبایل</b><div>${esc(s.mobile||'-')}</div></div><div class="card"><b>کد ملی</b><div>${esc(s.national_id||'-')}</div></div></div><div class="card" style="margin-top:12px"><b>موقعیت</b><div>${Number(s.latitude).toFixed(6)}, ${Number(s.longitude).toFixed(6)}</div></div><div class="row" style="margin-top:12px">${state.user.role==='INSPECTOR'&&state.activeMission?'<button class="btn primary" id="newInspection">ثبت بازرسی</button><button class="btn secondary" id="newWarning">ثبت اخطار</button>':''}<button class="btn ghost" id="close">بستن</button></div>`);$('#close').onclick=closeModal;if($('#newInspection'))$('#newInspection').onclick=()=>inspectionModal(s);if($('#newWarning'))$('#newWarning').onclick=()=>warningModal(s)}
function inspectionModal(s){modal(`<h2>ثبت بازرسی</h2><div class="field"><label>نتیجه</label><select id="ir"><option value="NO_ISSUE">بدون مشکل</option><option value="WARNING">اخطار</option><option value="FOLLOW_UP">نیازمند پیگیری</option><option value="OTHER">سایر</option></select></div><div class="field" style="margin-top:10px"><label>توضیحات</label><textarea id="in"></textarea></div><div class="row" style="margin-top:12px"><button class="btn primary" id="si">ثبت</button><button class="btn ghost" id="close">انصراف</button></div>`);$('#close').onclick=closeModal;$('#si').onclick=async()=>{try{await api('inspections',{method:'POST',body:JSON.stringify({shopId:s.id,missionId:state.activeMission,result:$('#ir').value,notes:$('#in').value})});closeModal();toast('بازرسی ثبت شد')}catch(e){toast(e.message)}}}
function warningModal(s){modal(`<h2>ثبت اخطار</h2><div class="field"><label>علت</label><input id="wr"></div><div class="field" style="margin-top:10px"><label>توضیحات</label><textarea id="wd"></textarea></div><div class="row" style="margin-top:12px"><button class="btn danger" id="sw">ثبت اخطار</button><button class="btn ghost" id="close">انصراف</button></div>`);$('#close').onclick=closeModal;$('#sw').onclick=async()=>{try{const d=await api('warnings',{method:'POST',body:JSON.stringify({shopId:s.id,missionId:state.activeMission,reason:$('#wr').value,description:$('#wd').value})});closeModal();toast('اخطار '+d.warningNumber+' ثبت شد')}catch(e){toast(e.message)}}}
function modal(content){let x=document.createElement('div');x.className='modal';x.id='modal';x.innerHTML=`<div class="modal-card">${content}</div>`;document.body.appendChild(x)}function closeModal(){$('#modal')?.remove()}
function missions(c){c.innerHTML=`<div class="page-head"><div><h1>مأموریت‌ها</h1><div class="muted">تاریخچه و مأموریت فعال</div></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>ID</th><th>وضعیت</th><th>شروع</th><th>پایان</th><th>مسافت</th><th></th></tr></thead><tbody>${state.missions.map(m=>`<tr><td>${esc(m.id.slice(0,8))}…</td><td><span class="pill ${m.status==='ACTIVE'?'ok':''}">${esc(m.status)}</span></td><td>${m.start_time?new Date(m.start_time).toLocaleString('fa-IR'): '-'}</td><td>${m.end_time?new Date(m.end_time).toLocaleString('fa-IR'):'-'}</td><td>${Math.round(m.distance||0)} m</td><td><button class="btn secondary" data-route="${m.id}">مسیر</button></td></tr>`).join('')}</tbody></table></div>`;c.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>routeModal(b.dataset.route))}
async function routeModal(id){try{const d=await api('route/'+id);modal(`<h2>جزئیات مأموریت</h2><div class="three grid"><div class="card"><b>وضعیت</b><div>${esc(d.mission.status)}</div></div><div class="card"><b>نقاط مسیر</b><div>${d.points.length}</div></div><div class="card"><b>مسافت</b><div>${Math.round(d.mission.distance||0)} متر</div></div></div><div class="card" style="margin-top:14px;padding:8px"><div class="map" id="routeMap"><div class="map-canvas" id="routeMapCanvas"></div></div><div class="muted" style="padding:8px 4px 2px">مسیر بر اساس ${d.points.length} نقطه واقعی GPS ذخیره‌شده در این مأموریت.</div></div><h3>Timeline</h3><div class="timeline">${d.events.map(e=>`<div class="event"><b>${new Date(e.timestamp).toLocaleString('fa-IR')}</b><div>${esc(e.type)}</div></div>`).join('')}</div><div class="row" style="margin-top:14px"><button class="btn ghost" id="close">بستن</button></div>`);$('#close').onclick=closeModal;drawHistoricalRouteMap(d.points,d.mission)}catch(e){toast(e.message)}}
function shops(c){c.innerHTML=`<div class="page-head"><div><h1>واحدهای صنفی</h1><div class="muted">${state.shops.length} رکورد در سازمان شما</div></div><div class="row">${state.user.role==='INSPECTOR'?'<button class="btn primary" id="newShop">+ ثبت واحد</button>':''}</div></div><div class="card"><div class="field"><label>جستجو</label><input id="search" placeholder="نام، صاحب یا صنف…"></div><div id="shopTable" style="margin-top:12px"></div></div>`;const render=()=>{const q=$('#search').value.toLowerCase();const a=state.shops.filter(s=>(s.name+' '+s.owner_name+' '+(s.category||'')).toLowerCase().includes(q));$('#shopTable').innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>واحد</th><th>صاحب</th><th>صنف</th><th>موقعیت</th><th></th></tr></thead><tbody>${a.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.owner_name)}</td><td>${esc(s.category||'-')}</td><td>${Number(s.latitude).toFixed(4)}, ${Number(s.longitude).toFixed(4)}</td><td><button class="btn secondary" data-shop="${s.id}">مشاهده</button></td></tr>`).join('')}</tbody></table></div>`;$('#shopTable').querySelectorAll('[data-shop]').forEach(b=>b.onclick=()=>shopModalById(b.dataset.shop))};$('#search').oninput=render;render();if($('#newShop'))$('#newShop').onclick=()=>shopModal()}
function genericList(c,title,type){c.innerHTML=`<div class="page-head"><div><h1>${title}</h1><div class="muted">داده‌های این بخش از API سازمانی خوانده می‌شوند.</div></div></div><div class="card"><div class="empty">برای مشاهده کامل ${title} در این نسخه، گزارش سازمانی و API آماده است. ثبت داده از جریان اصلی مأموریت انجام می‌شود.</div></div>`}
function monitoring(c){c.innerHTML=`<div class="page-head"><div><h1>نظارت زنده</h1><div class="muted">موقعیت لحظه‌ای بازرسان فعال از کانال Realtime دریافت می‌شود.</div></div></div><div class="grid two"><div class="card"><h3>بازرسان فعال</h3>${state.monitoring.map(m=>`<div class="row" style="justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--line)"><div><b>${m.first_name} ${m.last_name}</b><div class="muted">Mission ${esc(m.id.slice(0,8))}…</div></div><span class="pill ok">فعال</span></div>`).join('')||'<div class="empty">در حال حاضر مأموریت فعالی ثبت نشده است.</div>'}</div><div class="card"><h3>Realtime</h3><p class="muted">این پنل برای اتصال به WebSocket/SSE طراحی شده است. سرور فعلی SSE را در اختیار Frontend قرار می‌دهد.</p><div class="pill ok">SSE Ready</div></div></div>`}
function employees(c){c.innerHTML=`<div class="page-head"><div><h1>کارمندان</h1></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>نام</th><th>کد پرسنلی</th><th>موبایل</th><th>وضعیت</th></tr></thead><tbody>${state.employees.map(e=>`<tr><td>${e.firstName} ${e.lastName}</td><td>${e.personnelCode||'-'}</td><td>${e.mobile||'-'}</td><td><span class="pill ${e.status==='ACTIVE'?'ok':''}">${e.status}</span></td></tr>`).join('')}</tbody></table></div>`}
function routes(c){c.innerHTML=`<div class="page-head"><div><h1>مسیرها</h1><div class="muted">بازپخش مسیرهای ذخیره‌شده</div></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>Mission</th><th>شروع</th><th>پایان</th><th>نقاط</th><th>Replay</th></tr></thead><tbody>${state.missions.map(m=>`<tr><td>${esc(m.id.slice(0,8))}…</td><td>${m.start_time?new Date(m.start_time).toLocaleString('fa-IR'):'-'}</td><td>${m.end_time?new Date(m.end_time).toLocaleString('fa-IR'):'-'}</td><td>-</td><td><button class="btn secondary" data-r="${m.id}">▶ Replay</button></td></tr>`).join('')}</tbody></table></div>`;c.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>routeModal(b.dataset.r))}
async function reports(c){let d;try{d=await api('reports')}catch(e){return toast(e.message)}c.innerHTML=`<div class="page-head"><div><h1>گزارش‌ها</h1><div class="muted">گزارش‌های محدود به سازمان شما</div></div><button class="btn primary" id="excel">Export Excel</button></div><div class="grid stats"><div class="card stat"><div class="label">واحدها</div><div class="value">${d.shops.length}</div></div><div class="card stat"><div class="label">بازرسی</div><div class="value">${d.inspections.length}</div></div><div class="card stat"><div class="label">اخطار</div><div class="value">${d.warnings.length}</div></div><div class="card stat"><div class="label">مأموریت</div><div class="value">${d.missions.length}</div></div></div><div class="card" style="margin-top:14px"><h3>خلاصه</h3><p class="muted">خروجی XLSX واقعی در Production باید با کتابخانه Excel یا سرویس Backend تکمیل شود؛ این نسخه خروجی استاندارد Excel-compatible را از داده‌های مجاز سازمان تولید می‌کند.</p></div>`;$('#excel').onclick=()=>exportExcel(d)}
function exportExcel(d){const rows=[['Missions'],['ID','Status','Start','End','Distance'],...d.missions.map(m=>[m.id,m.status,m.start_time||'',m.end_time||'',m.distance||0]),[],['Shops'],['ID','Name','Owner','Category','Lat','Lng'],...d.shops.map(s=>[s.id,s.name,s.owner_name,s.category||'',s.latitude,s.longitude]),[],['Inspections'],['ID','Shop','Inspector','Result','Timestamp'],...d.inspections.map(x=>[x.id,x.shop_id,x.inspector_id,x.result,x.timestamp]),[],['Warnings'],['ID','Warning Number','Shop','Reason','Status'],...d.warnings.map(x=>[x.id,x.warning_number,x.shop_id,x.reason,x.status])];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pakdasht-inspection-report.csv';a.click();URL.revokeObjectURL(a.href)}
function profile(c){c.innerHTML=`<div class="page-head"><div><h1>پروفایل</h1></div></div><div class="card"><div class="form-grid"><div><b>نام</b><div>${esc(state.user.firstName)} ${esc(state.user.lastName)}</div></div><div><b>نقش</b><div>${state.user.role}</div></div><div><b>کد پرسنلی</b><div>${esc(state.user.personnelCode||'-')}</div></div><div><b>موبایل</b><div>${esc(state.user.mobile||'-')}</div></div></div></div>`}
window.addEventListener('online',async()=>{state.online=true;updateNet();await syncQueue()});window.addEventListener('offline',()=>{state.online=false;updateNet()});
async function syncQueue(){if(!state.online)return;let q=[];try{q=await IDB.all()}catch{q=JSON.parse(localStorage.getItem('syncQueue')||'[]')}const remaining=[];for(const x of q){try{if(x.type==='track_point'&&x.missionId){await api(`missions/${x.missionId}/track`,{method:'POST',body:JSON.stringify(x.payload)});try{await IDB.del(x.id)}catch{}continue}}catch(e){x.status='failed';x.attempts=(x.attempts||0)+1;x.lastError=e.message}remaining.push(x)}localStorage.setItem('syncQueue',JSON.stringify(remaining))}
async function connectSSE(){if(state.user?.role!=='MANAGER'||!state.online)return;try{const r=await fetch(API_BASE+'sse',{credentials:'include',headers:state.token?{Authorization:`Bearer ${state.token}`}:{}});if(!r.ok)throw new Error('SSE '+r.status);const reader=r.body?.getReader();if(!reader)return;const dec=new TextDecoder();let buf='';while(state.online){const {value,done}=await reader.read();if(done)break;buf+=dec.decode(value,{stream:true});const events=buf.split('\n\n');buf=events.pop()||'';for(const block of events){const type=(block.match(/^event:\s*(.+)$/m)||[])[1];const data=(block.match(/^data:\s*(.+)$/m)||[])[1];if(type==='tracking.point'&&data){const d=JSON.parse(data);toast('موقعیت جدید دریافت شد');state.monitoring=state.monitoring.map(x=>x.id===d.missionId?{...x,latitude:d.latitude,longitude:d.longitude}:x);if(state.page==='monitoring')renderPage()}}}}catch{setTimeout(connectSSE,5000)}}
async function boot(){if(!state.user){login();return}try{const m=await api('auth/me');state.user=m.user;await load();renderShell();if(state.user.role==='INSPECTOR'&&state.activeMission)beginWatch();connectSSE();syncQueue()}catch{state.token=null;state.user=null;save();login()}}
boot();

if('serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).catch(()=>{});}
